	private static Map<Value, Integer> valueBag(List<Value> values) {
		Map<Value, Integer> bag = new HashMap<>();
		for (Value value : values) {
			bag.merge(value, 1, Integer::sum);
		}
		return bag;
	}

	private static List<Statement> expressionOrderData() {
		var vf = NativeCompositeOriginFixture.VF;
		return List.of(
				vf.createStatement(NativeCompositeOriginFixture.iri("s0"), NativeCompositeOriginFixture.iri("p"),
						vf.createLiteral("b")),
				vf.createStatement(NativeCompositeOriginFixture.iri("s1"), NativeCompositeOriginFixture.iri("p"),
						vf.createLiteral("a")),
				vf.createStatement(NativeCompositeOriginFixture.iri("s2"), NativeCompositeOriginFixture.iri("p"),
						vf.createLiteral("c")));
	}

	private static QueryRoot expressionOrderRoot(String functionUri, boolean topK) {
		TupleExpr duplicates = new Union(pattern("p", "k"), pattern("p", "k"));
		Projection projected = new Projection(duplicates, columns("IDENTITY"));
		TupleExpr ordered = new Order(projected,
				List.of(new OrderElem(new FunctionCall(functionUri, Var.of("k")))));
		if (topK) {
			ordered = new Slice(ordered, 0, 2);
		}
		return new QueryRoot(ordered);
	}

	private static QueryRoot bnodeExpressionOrderRoot(String functionUri, boolean topK) {
		TupleExpr duplicates = new Union(pattern("p", "k"), pattern("p", "k"));
		Projection projected = new Projection(duplicates, columns("IDENTITY"));
		FunctionCall key = new FunctionCall(functionUri,
				new BNodeGenerator(new ValueConstant(NativeCompositeOriginFixture.VF.createLiteral("same-label"))));
		TupleExpr ordered = new Order(projected, List.of(new OrderElem(key)));
		if (topK) {
			ordered = new Slice(ordered, 0, 2);
		}
		return new QueryRoot(ordered);
	}

	private static void enableOrderSummary(QueryRoot root, boolean topK) {
		root.setExecutionSummaryEnabled(true);
		Order ordered = topK ? (Order) ((Slice) root.getArg()).getArg() : (Order) root.getArg();
		ordered.setExecutionSummaryEnabled(true);
		ordered.getArg().setExecutionSummaryEnabled(true);
		if (ordered.getArg() instanceof Projection projection) {
			projection.getArg().setExecutionSummaryEnabled(true);
		}
	}

	private static final class CountingOrderKeyFunction implements Function {
		private final String uri = "urn:rdf4j:test:counted-order-key:" + UUID.randomUUID();
		private final AtomicInteger calls = new AtomicInteger();
		private final List<Value> arguments = new ArrayList<>();

		@Override
		public String getURI() {
			return uri;
		}

		@Override
		public Determinism getDeterminism() {
			return Determinism.DETERMINISTIC;
		}

		@Override
		public synchronized Value evaluate(ValueFactory valueFactory, Value... args) {
			calls.incrementAndGet();
			arguments.add(args[0]);
			return args[0];
		}

		private synchronized void reset() {
			calls.set(0);
			arguments.clear();
		}

		private synchronized List<Value> arguments() {
			return List.copyOf(arguments);
		}
	}

	private static QueryRoot root(Case test, TupleExpr body) {
		TupleExpr input = test.innerOrder ? new Order(body, List.of(new OrderElem(Var.of("k")))) : body;
		TupleExpr projected = new Projection(input, columns(test.projection));
		if (test.modifier.equals("DISTINCT"))
			projected = new Distinct(projected);
		else if (test.modifier.equals("REDUCED"))
			projected = new Reduced(projected);
		TupleExpr result = test.innerOrder ? projected : new Order(projected, List.of(new OrderElem(Var.of("k"))));
		if (test.limit >= 0)
			result = new Slice(result, test.offset, test.limit);
		return new QueryRoot(result);
	}

	private static ProjectionElemList columns(String shape) {
		var result = new ProjectionElemList();
		if (shape.equals("ALIAS"))
			result.addElement(new ProjectionElem("s", "alias"));
		else if (shape.startsWith("DUP")) {
			result.addElement(new ProjectionElem("s", "alias"));
			result.addElement(new ProjectionElem("payload", "alias"));
			if (shape.equals("DUP_MISSING"))
				result.addElement(new ProjectionElem("notProduced", "alias"));
		} else
			result.addElement(new ProjectionElem("s"));
		result.addElement(new ProjectionElem("k"));
		if (shape.equals("IDENTITY") || shape.equals("ALIAS"))
			result.addElement(new ProjectionElem("payload"));
		// A free output is a real Projection boundary, keeping this fixture on the naturally selected staged owner.
		for (String name : List.of("missing", "marker", "external", "privateGraph"))
			result.addElement(new ProjectionElem(name));
		return result;
	}

	private static TupleExpr body(boolean duplicates) {
		TupleExpr body = new LeftJoin(pattern("p", "k"), pattern("value", "payload"));
		return duplicates ? new Union(body, body.clone()) : body;
	}

	private static StatementPattern pattern(String predicate, String object) {
		return new StatementPattern(Var.of("s"),
				Var.of("_" + predicate, NativeCompositeOriginFixture.iri(predicate), true, true), Var.of(object));
	}

	private static List<Statement> data() {
		var vf = NativeCompositeOriginFixture.VF;
		return List.of(
				vf.createStatement(NativeCompositeOriginFixture.iri("s2"), NativeCompositeOriginFixture.iri("p"),
						NativeCompositeOriginFixture.iri("tied")),
				vf.createStatement(NativeCompositeOriginFixture.iri("s2"), NativeCompositeOriginFixture.iri("value"),
						NativeCompositeOriginFixture.iri("z")),
				vf.createStatement(NativeCompositeOriginFixture.iri("s0"), NativeCompositeOriginFixture.iri("p"),
						NativeCompositeOriginFixture.iri("tied")),
				vf.createStatement(NativeCompositeOriginFixture.iri("s1"), NativeCompositeOriginFixture.iri("p"),
						NativeCompositeOriginFixture.iri("tied")),
				vf.createStatement(NativeCompositeOriginFixture.iri("s1"), NativeCompositeOriginFixture.iri("value"),
						NativeCompositeOriginFixture.iri("a")));
	}

	private static BindingSet frame(String mode) {
		if (mode.equals("EMPTY"))
			return EmptyBindingSet.getInstance();
		QueryBindingSet input = new QueryBindingSet();
		if (mode.equals("NULL")) {
			input.setBinding("marker", null);
			return input;
		}
		if (mode.equals("REQUEST")) {
			input.setBinding("external", NativeCompositeOriginFixture.VF.createLiteral("same", "EN"));
			return BindingSetOrigin.requestInput(input);
		}
		var graph = NativeCompositeOriginFixture.iri("graph");
		input.setBinding("privateGraph", graph);
		return GraphFrameBindings.supply(input, "privateGraph", graph);
	}

