	private static void assertFailure(QueryEvaluationStep step, RowsFunction function) {
		List<BindingSet> published = new ArrayList<>();
		Throwable caught = null;
		try (var rows = step.evaluate(EmptyBindingSet.getInstance())) {
			while (rows.hasNext())
				published.add(rows.next());
		} catch (RuntimeException | Error failure) {
			caught = failure;
		}
		Reader used = function.readers.get(function.readers.size() - 1);
		assertSame(used.primary, caught);
		assertTrue(published.isEmpty());
		assertEquals(1, used.pulled);
		assertEquals(1, used.closes);
		if (used.closeFailure) {
			assertEquals(1, caught.getSuppressed().length);
			assertSame(used.cleanup, caught.getSuppressed()[0]);
		} else
			assertEquals(0, caught.getSuppressed().length);
	}

	private static QueryRoot functionRoot(RowsFunction function, boolean distinct, boolean topK) {
		TupleFunctionCall call = new TupleFunctionCall();
		call.setURI(function.getURI());
		call.addResultVars(Var.of("k"), Var.of("rep"));
		TupleExpr node = new Projection(call, new ProjectionElemList(new ProjectionElem("k"), new ProjectionElem("rep"),
				new ProjectionElem("missing")));
		if (distinct)
			node = new Distinct(node);
		node = new Order(node, List.of(new OrderElem(Var.of("k"))));
		if (topK)
			node = new Slice(node, 0L, 1L);
		return new QueryRoot(node);
	}

	private static final class RowsFunction implements TupleFunction {
		private final String uri = "urn:rdf4j:test:order-row-producer:" + UUID.randomUUID();
		private final List<? extends List<? extends Value>> rows;
		private final boolean fail, closeFailure;
		private final List<Reader> readers = new ArrayList<>();

		RowsFunction(List<? extends List<? extends Value>> rows, boolean fail, boolean closeFailure) {
			this.rows = rows;
			this.fail = fail;
			this.closeFailure = closeFailure;
		}

		@Override
		public String getURI() {
			return uri;
		}

		@Override
		public org.eclipse.rdf4j.common.iteration.CloseableIteration<? extends List<? extends Value>> evaluate(
				ValueFactory factory, Value... args) {
			Reader reader = new Reader(rows, fail, closeFailure);
			readers.add(reader);
			return reader;
		}
	}

	private static final class Reader extends AbstractCloseableIteration<List<? extends Value>>
			implements CooperativeCancellation {
		final QueryEvaluationException primary = new QueryEvaluationException("ordered input failure"),
				cleanup = new QueryEvaluationException("ordered input close failure");
		final List<? extends List<? extends Value>> rows;
		final boolean fail, closeFailure;
		int pulled, closes, cancellations;

		Reader(List<? extends List<? extends Value>> rows, boolean fail, boolean closeFailure) {
			this.rows = rows;
			this.fail = fail;
			this.closeFailure = closeFailure;
		}

		@Override
		public boolean hasNext() {
			if (isClosed())
				return false;
			if (pulled < rows.size())
				return true;
			if (fail)
				throw primary;
			return false;
		}

		@Override
		public List<? extends Value> next() {
			if (!hasNext())
				throw new java.util.NoSuchElementException();
			return rows.get(pulled++);
		}

		@Override
		public void remove() {
			throw new UnsupportedOperationException();
		}

		@Override
		public boolean requestCancellation() {
			cancellations++;
			close();
			return true;
		}

		@Override
		protected void handleClose() {
			closes++;
			if (closeFailure)
				throw cleanup;
		}
	}

