	@ParameterizedTest(name = "delivered BNODE state TopK={0}, typed={1}")
	@MethodSource("deterministicExpressionOrders")
	void orderedDeliveryRetainsTheCapturedOccurrenceLabelState(boolean topK, boolean typed, TestReporter reporter) {
		CountingOrderKeyFunction function = new CountingOrderKeyFunction();
		FunctionRegistry registry = FunctionRegistry.getInstance();
		Function previous = registry.add(function).orElse(null);
		try {
			// Six real UNION occurrences of one statement have identical visible projected mappings. The
			// independent TopK selections therefore cannot differ merely because generated BNODE spellings do.
			var source = SealedBoundaryTestSupport.source(List.of(expressionOrderData().get(0)));
			QueryRoot premiseRoot = equivalentOccurrenceOrderRoot(function.getURI(), topK);
			Order premiseOrder = topK ? (Order) ((Slice) premiseRoot.getArg()).getArg() : (Order) premiseRoot.getArg();
			List<BindingSet> equivalentInputs = SealedBoundaryTestSupport.drain(
					SealedBoundaryTestSupport.ordinary(source, true).precompile(premiseOrder.getArg().clone()),
					EmptyBindingSet.getInstance(), false);
			assertEquals(6, equivalentInputs.size(), "ordinary actual pre-ORDER solution occurrences");
			for (BindingSet row : equivalentInputs)
				SealedBoundaryTestSupport.assertRows(List.of(equivalentInputs.get(0)), List.of(row));
			ContinuationObservation reference = observeOrderContinuation(source, function, topK, false, false,
					reporter);
			ContinuationObservation ordinary = observeOrderContinuation(source, function, topK, typed, false, reporter);
			ContinuationObservation nativeResult = observeOrderContinuation(source, function, topK, typed, true,
					reporter);
			// Complete the unconverted ordinary characterization and both identical-adapter executions before
			// comparing. BNODE makes this ordinary ORDER volatile even if its wrapping function is pinned: do
			// not impose the stable OrderComparator snapshot protocol or assume its FILTER accepted every row.
			assertContinuationCount(reference, topK, "ordinary without adapter");
			assertContinuationCount(ordinary, topK, "ordinary through the identical adapter");
			assertContinuationCount(nativeResult, topK, "native through the identical adapter");
			SealedBoundaryTestSupport.assertRows(ordinary.rows(), nativeResult.rows());
			assertEquals(source.opened, source.closed);
		} finally {
			registry.remove(function);
			if (previous != null)
				registry.add(previous);
		}
	}

	private static QueryRoot equivalentOccurrenceOrderRoot(String functionUri, boolean topK) {
		TupleExpr occurrences = pattern("p", "k");
		for (int occurrence = 1; occurrence < 6; occurrence++)
			occurrences = new Union(occurrences, pattern("p", "k"));
		Projection projected = new Projection(occurrences, columns("IDENTITY"));
		FunctionCall key = new FunctionCall(functionUri,
				new BNodeGenerator(new ValueConstant(NativeCompositeOriginFixture.VF.createLiteral("same-label"))));
		TupleExpr ordered = new Order(projected, List.of(new OrderElem(key)));
		if (topK)
			ordered = new Slice(ordered, 0, 2);
		return new QueryRoot(ordered);
	}

	private record ContinuationObservation(List<BindingSet> rows, List<Value> captured, List<Value> observed) {
	}

	private static void assertContinuationCount(ContinuationObservation actual, boolean topK, String label) {
		int candidates = topK ? 2 : 6;
		assertEquals(candidates, actual.observed().size(), label + ": one real FILTER evaluation per input occurrence");
		assertEquals(candidates, new HashSet<>(actual.observed()).size(),
				label + ": different observed occurrences have different labels");
		assertEquals(6, new HashSet<>(actual.captured()).size(),
				label + ": actual key inputs, not an inferred snapshot protocol");
	}

	private static ContinuationObservation observeOrderContinuation(
			LmdbNativeRepeatedStatementTermRoleTest.MemorySource source, CountingOrderKeyFunction function,
			boolean topK, boolean typed, boolean nativeEngine, TestReporter reporter) {
		QueryRoot root = equivalentOccurrenceOrderRoot(function.getURI(), topK);
		var ordinaryStrategy = SealedBoundaryTestSupport.ordinary(source, true);
		Order order = topK ? (Order) ((Slice) root.getArg()).getArg() : (Order) root.getArg();
		assertFalse(org.eclipse.rdf4j.query.algebra.evaluation.util.QueryEvaluationUtility
				.isRepeatable(order.getElements().get(0).getExpr()),
				"the real BNODE key selects ordinary volatile-key policy even after function pinning");
		var ordinaryContext = new org.eclipse.rdf4j.query.algebra.evaluation.impl.QueryEvaluationContext.Minimal(
				null, source.getValueFactory(), source.getComparator());
		if (nativeEngine)
			enableOrderSummary(root, topK);
		QueryEvaluationStep step = nativeEngine
				? SealedBoundaryTestSupport.nativeStrategy(source, true).precompile(root)
				: ordinaryStrategy.precompile(root, ordinaryContext);
		function.reset();
		int openedAtCompile = source.opened;
		List<BindingSet> result = new ArrayList<>();
		List<Value> captured;
		CapturedLabelProbe probe;
		try (var ordered = step.evaluate(EmptyBindingSet.getInstance())) {
			assertTrue(ordered.hasNext(), "the real ORDER/TopK prepares its nonempty input before the observer");
			captured = function.arguments();
			assertEquals(6, new HashSet<>(captured).size(),
					"six source occurrences actually evaluated labelled BNODE keys");
			var owner = NativeExecutionContextCarrier.contextOf(ordered);
			var context = nativeEngine ? owner == null ? null : owner.genericContextOrNull() : ordinaryContext;
			assertTrue(context != null, "use the scalar context that actually produced the BNODE keys");
			if (nativeEngine) {
				SealedBoundaryTestSupport.orderStage(root, topK);
				assertTrue(source.opened > openedAtCompile, "this ordered invocation consumed native record readers");
			}
			// This is only a representation adapter, with no Extend, standalone scalar API, new query entry or
			// logical solution-producing operator between ORDER and the semantic FILTER observer.
			org.eclipse.rdf4j.common.iteration.CloseableIteration<BindingSet> continuation = typed
					? NativeResultSteps.rdf(NativeResultSteps.open(ignored -> ordered, EmptyBindingSet.getInstance()))
					: ordered;
			probe = new CapturedLabelProbe(new HashSet<>(captured));
			FunctionRegistry.getInstance().add(probe);
			try {
				var label = new ValueConstant(NativeCompositeOriginFixture.VF.createLiteral("same-label"));
				var condition = new org.eclipse.rdf4j.query.algebra.SameTerm(new BNodeGenerator(label),
						new FunctionCall(probe.getURI(), new BNodeGenerator(label.clone())));
				var filter = new org.eclipse.rdf4j.query.algebra.Filter(root.getArg().clone(), condition);
				org.eclipse.rdf4j.common.iteration.CloseableIteration<BindingSet> filtered;
				try (var ignored = context.getBlankNodeAllocationScope().activate()) {
					var compiled = ordinaryStrategy.precompile(condition, context);
					filtered = new org.eclipse.rdf4j.query.algebra.evaluation.iterator.FilterIterator(
							filter, continuation, compiled, ordinaryStrategy);
				}
				try (filtered) {
					while (filtered.hasNext())
						result.add(filtered.next());
				}
			} finally {
				FunctionRegistry.getInstance().remove(probe);
			}
			if (nativeEngine)
				SealedBoundaryTestSupport.report(root, reporter);
		}
		assertEquals(source.opened, source.closed);
		reporter.publishEntry("sameOccurrenceContinuation", "native=" + nativeEngine + ", typed=" + typed
				+ ", topK=" + topK + ", capturedDistinct=" + new HashSet<>(captured).size()
				+ ", observedDistinct=" + new HashSet<>(probe.observed).size() + ", rows=" + result.size()
				+ ", observedAmongCaptured=" + probe.observed.stream().filter(probe.captured::contains).count()
				+ ", ordinaryKeyPolicy=volatile-bnode");
		return new ContinuationObservation(List.copyOf(result), captured, List.copyOf(probe.observed));
	}

	private static final class CapturedLabelProbe implements Function {
		private final String uri = "urn:rdf4j:test:captured-order-label:" + UUID.randomUUID();
		private final java.util.Set<Value> captured;
		private final List<Value> observed = new ArrayList<>();

		private CapturedLabelProbe(java.util.Set<Value> captured) {
			this.captured = captured;
		}

		@Override
		public String getURI() {
			return uri;
		}

		@Override
		public Determinism getDeterminism() {
			return Determinism.DETERMINISTIC;
		}

		@Override
		public Value evaluate(ValueFactory factory, Value... args) {
			observed.add(args[0]);
			return captured.contains(args[0]) ? args[0] : factory.createLiteral(false);
		}
	}

